import{_ as r,a0 as l,w as u,s as p,I as n,x as t,a1 as a,A as o,ao as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const V=JSON.parse('{"title":"Voyager Linux 23.04：具有华丽外观且无 Snap 的 Ubuntu 体验 | LCTT x X-CMD","titleTemplate":false,"description":"Voyager Linux 23.04：具有华丽外观且无 Snap 的 Ubuntu 体验 | LCTT (202305) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Voyager Linux 23.04：具有华丽外观且无 Snap 的 Ubuntu 体验 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Voyager Linux 23.04：具有华丽外观且无 Snap 的 Ubuntu 体验 | LCTT (202305) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202305/20230427.0 ⭐️⭐️ Voyager Linux 23.04 Snap-free Ubuntu Experience with A Gorgeous Look","title":"Voyager Linux 23.04：具有华丽外观且无 Snap 的 Ubuntu 体验","tag":"202305","desc":""},"relativePath":"202305/20230427.0 ⭐️⭐️ Voyager Linux 23.04 Snap-free Ubuntu Experience with A Gorgeous Look.md","filePath":"[post].md"}'),g={name:"202305/20230427.0 ⭐️⭐️ Voyager Linux 23.04 Snap-free Ubuntu Experience with A Gorgeous Look.md"};function d(x,e,b,y,m,f){const i=l("Link");return u(),p("div",null,[e[24]||(e[24]=n("h1",{id:"voyager-linux-23-04-具有华丽外观且无-snap-的-ubuntu-体验",tabindex:"-1"},[t("Voyager Linux 23.04：具有华丽外观且无 Snap 的 Ubuntu 体验 "),n("a",{class:"header-anchor",href:"#voyager-linux-23-04-具有华丽外观且无-snap-的-ubuntu-体验","aria-label":"Permalink to “Voyager Linux 23.04：具有华丽外观且无 Snap 的 Ubuntu 体验”"},"​")],-1)),e[25]||(e[25]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202305/17/113613lyh2qod5jldqeu91.jpg",alt:""})],-1)),e[26]||(e[26]=n("blockquote",null,[n("p",null,"新版本的 Voyager Linux 23.04 已经来到，我率先试驾以了解更多信息。")],-1)),n("p",null,[e[1]||(e[1]=t("在我去年年初上次 ",-1)),a(i,{href:"https://www.debugpoint.com/voyager-live-linux-review-2022/"},{default:o(()=>[...e[0]||(e[0]=[t("测评",-1)])]),_:1}),e[2]||(e[2]=t(" 时，它还是一个崭露头角的发行版，提供了很棒的 Ubuntu LTS 体验。从那时起，这个发行版的方向发生了一些变化。因此，我觉得是时候进行另一轮试驾了。",-1))]),e[27]||(e[27]=n("p",null,"顺便说一句，Voyager Linux 基于 Ubuntu Linux，针对 GNOME 桌面进行了出色的定制。之前，它只跟随 Ubuntu 长期支持（LTS）版本发布，但从去年开始，它也可跟随短期 Ubuntu 版本发布。",-1)),n("p",null,[e[4]||(e[4]=t("在 ",-1)),a(i,{href:"https://www.debugpoint.com/ubuntu-23-04-features/"},{default:o(()=>[...e[3]||(e[3]=[t("Ubuntu 23.04 “Lunar Lobster”",-1)])]),_:1}),e[5]||(e[5]=t(" 发布后，Voyager 团队宣布发布了 Voyager 23.04。",-1))]),e[28]||(e[28]=s('<h3 id="voyager-linux-23-04-测评" tabindex="-1">Voyager Linux 23.04 测评 <a class="header-anchor" href="#voyager-linux-23-04-测评" aria-label="Permalink to “Voyager Linux 23.04 测评”">​</a></h3><p>与 Voyager 22.04 版本相比，此版本的 ISO 大小增加了约 30%。这可能主要是由于 Ubuntu 自己的软件包库。安装很顺利，但安装程序需要至少 24 GB 的存储空间（硬性要求）。但是，它使用旧的 Uniquity 安装程序，而不是新的基于 Flutter 的 Ubuntu 安装程序。</p><h4 id="外观及使用感受" tabindex="-1">外观及使用感受 <a class="header-anchor" href="#外观及使用感受" aria-label="Permalink to “外观及使用感受”">​</a></h4><p>如果你运行的是早期版本的 Voyager Linux，你首先会注意到新版的外观精美。GNOME 桌面现在更具个性化，使用了 “Kora” 主题和许多扩展程序。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/04/Voyager-23.04-Desktop-GNOME.jpg" alt="Voyager 23.04 桌面（GNOME）"></p><p>在底部，你可以看到默认的程序坞，并通过 “Blur my shell” 扩展将其变成了透明的。此外，这一版本还预装了一系列扩展，并通过适当的设置启用，以便让 GNOME 桌面更好看。</p><p>值得重点一提的扩展是非常棒的 “Arc Menu”，可以下拉访问所有系统应用程序和资源。此外，“Dash to Dock”、“Blur my shell” 和 “Battery Indicator” 也是一些很有用的扩展应用。以下是 Voyager Linux 23.04 中预装的扩展列表：</p><ul><li>Arch menu</li><li>Battery time</li><li>Blur my shell</li><li>Burn my windows</li><li>Caffeine</li><li>Clipboard history</li><li>Compiz alike magic lamp effect</li><li>Compiz windows effect</li><li>Custom hot corners – Extended</li><li>Dash to Dock</li><li>Desktop Cube</li><li>EasyScreenCast</li><li>Gradient Top Bar</li><li>Lock keys</li><li>Replace Activities Label</li><li>Screen Rotate</li><li>SettingsCenter</li><li>Simple net speed</li><li>Space Bar</li><li>Sur Clock</li><li>Use Avatar in Quick Settings</li></ul><p>所有这些都使桌面在美观的同时超级高效。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/04/Arc-Menu-with-workspace-view.jpg" alt="带工作区示图的 Arc Menu"></p><h4 id="应用、snap-和-flatpak" tabindex="-1">应用、Snap 和 Flatpak <a class="header-anchor" href="#应用、snap-和-flatpak" aria-label="Permalink to “应用、Snap 和 Flatpak”">​</a></h4><p>尽管 Voyager Linux 是基于 Ubuntu 的，但默认情况下完全不包含 Snap。此外，Voyager Linux 23.04 也没有支持 Ubuntu 从该版本开始删除 Flatpak 的决定。因此，总而言之，Voyager Linux 23.04 中默认支持的是 Flatpak，而没有任何 Snap 的痕迹。不仅如此，Firefox 网络浏览器是由原生 deb 模块打包的，而不是 Snap 版本。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/04/Voyager-Linux-23.04-comes-with-default-Flatpak.jpg" alt="Voyager Linux 23.04 自带默认 Flatpak"></p><p>应用程序列表很庞大且健全。主要应用程序包括 Gedit 文本编辑器、“文件”应用、Firefox 网络浏览器、GIMP 和 LibreOffice 套件。还包括 Thunderbird 电子邮件客户端、Remmina 远程连接应用程序、Transmission Torrent 客户端和 Pidgin 通讯软件。</p><p>Voyager 包括 Pitivi、MPV 和 Rhythmbox，均可用于播放视频和音乐。对于工作和文档处理，它提供了地图、日历、Foliate 阅读器应用程序、KeePassXC 和 Scrcpy 安卓屏幕镜像工具。</p><p>由于主 ISO 文件包括了 Xfce 和 GNOME 桌面，因此你也可以体验一些原生 Xfce 应用程序。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/04/Voyager-Linux-Xfce-Edition-2304.jpg" alt="Voyager Linux Xfce 版本（23.04）"></p><h4 id="box-voyager" tabindex="-1">Box Voyager <a class="header-anchor" href="#box-voyager" aria-label="Permalink to “Box Voyager”">​</a></h4><p>Voyager Linux 带有自己的很棒的小应用，称为 “Box Voyager”，它让你可以一键访问所有桌面自定义设置。它有一个配置项列表，你可以直接使用此应用程序启动相应的设置。</p><p>此外，要进行更多自定义设置，你可以使用 Voyager Linux 中预装的多个 Conky 主题。 无需面对安装和配置 Conky 的麻烦。（LCTT 译注：Conky 是一个应用于桌面环境的系统监视软件，可以在桌面上监控系统运行状态、网络状态等一系列参数，而且可自由定制。）</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/04/Box-Voyager-and-Conky-Control.jpg" alt="Box Voyager 和 Conky Control"></p><h4 id="性能表现" tabindex="-1">性能表现 <a class="header-anchor" href="#性能表现" aria-label="Permalink to “性能表现”">​</a></h4><p>安装了所有定制和扩展后，其性能表现令人印象深刻。它在闲置时占用 1.3 GB 的内存，CPU 使用率为 1%。但是，随着你安装和打开更多应用程序，性能指标可能会上升。</p><p>然而，由于预装了许多应用程序和 Xfce 桌面，它的安装需要大约 14 GB 的磁盘空间。另外，正如我之前提到的，整个安装需要 24 GB 的可用磁盘空间。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/04/Voyager-Linux-Performance.jpg" alt="Voyager Linux 性能"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>在测评了 Voyager Linux 23.04 之后，我相信它是一个理想的、可以日常使用的非 Snap Ubuntu 变体。如果你不喜欢 Ubuntu GNOME 的默认外观，并且正在寻找具有稳定的 Ubuntu 长期支持/短期基础，且设计吸引人的预配置发行版，那么 Voyager Linux 可能是你的完美选择。</p><p>此外，最棒的是在同样的 Ubuntu 基础上还有一个 Xfce 桌面可以选择。试一试吧。</p>',28)),n("p",null,[e[7]||(e[7]=t("你可以在其 ",-1)),a(i,{href:"https://voyagerlive.org/"},{default:o(()=>[...e[6]||(e[6]=[t("官方网站",-1)])]),_:1}),e[8]||(e[8]=t(" 下载 Voyager Linux。",-1))]),e[29]||(e[29]=n("p",null,[n("em",null,"（题图：MJ/2deebcdf-7e04-43bc-beaf-7059e80b8057）")],-1)),e[30]||(e[30]=n("hr",null,null,-1)),n("p",null,[e[10]||(e[10]=t("via: ",-1)),a(i,{href:"https://www.debugpoint.com/voyager-linux-review-23-04/"},{default:o(()=>[...e[9]||(e[9]=[t("https://www.debugpoint.com/voyager-linux-review-23-04/",-1)])]),_:1})]),n("p",null,[e[15]||(e[15]=t("作者：",-1)),a(i,{href:"https://www.debugpoint.com/author/admin1/"},{default:o(()=>[...e[11]||(e[11]=[t("Arindam",-1)])]),_:1}),e[16]||(e[16]=t(" 选题：",-1)),a(i,{href:"https://github.com/lkxed/"},{default:o(()=>[...e[12]||(e[12]=[t("lkxed",-1)])]),_:1}),e[17]||(e[17]=t(" 译者：",-1)),a(i,{href:"https://github.com/XiaotingHuang22"},{default:o(()=>[...e[13]||(e[13]=[t("XiaotingHuang22",-1)])]),_:1}),e[18]||(e[18]=t(" 校对：",-1)),a(i,{href:"https://github.com/wxy"},{default:o(()=>[...e[14]||(e[14]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[21]||(e[21]=t("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[19]||(e[19]=[t("LCTT",-1)])]),_:1}),e[22]||(e[22]=t(" 原创编译，",-1)),a(i,{href:"https://linux.cn/"},{default:o(()=>[...e[20]||(e[20]=[t("Linux中国",-1)])]),_:1}),e[23]||(e[23]=t(" 荣誉推出",-1))])])}const k=r(g,[["render",d]]);export{V as __pageData,k as default};
